DECLARE @Anul INT =
    TRY_CONVERT(INT, N'[GetOrSession:YearV]');

DECLARE @Luna INT =
    TRY_CONVERT(INT, N'[GetOrSession:MonthV]');

DECLARE @TotalSucursale INT;
DECLARE @FisiereGenerate INT;

SELECT
    @TotalSucursale =
        COUNT(DISTINCT LTRIM(RTRIM(s.CodSucursala)))
FROM app.Sucursala AS s
WHERE NULLIF(LTRIM(RTRIM(s.CodSucursala)), N'') IS NOT NULL;

SELECT
    @FisiereGenerate =
        COUNT(DISTINCT LTRIM(RTRIM(fe.CodSucursala)))
FROM app.FisierEdenred AS fe

INNER JOIN Files AS f
    ON f.FileId = fe.FileId

INNER JOIN app.Sucursala AS s
    ON LTRIM(RTRIM(s.CodSucursala))
     = LTRIM(RTRIM(fe.CodSucursala))

WHERE fe.Anul = @Anul
  AND fe.Luna = @Luna;

SELECT
    CASE
        WHEN @TotalSucursale > 0
         AND ISNULL(@FisiereGenerate, 0) = @TotalSucursale
        THEN 1
        ELSE 0
    END AS TokenStatusFisiereEdenred;
